    // Drive on falling edge, give the synchronous ROM exactly one rising edge,
    // then read AFTER the NBA/combinational settling window (not a #1-only read).
    task sample_pixel;
        input integer px,py;
        begin
            @(negedge pixel_clk);x=px;y=py;
            @(posedge pixel_clk);#1;checks=checks+1;
            if((^{red,green,blue})===1'bx)$fatal(1,"X/Z pixel (%0d,%0d)",px,py);
        end
    endtask
    task expect_pixel;
        input integer px,py;
