            for(ci=0;ci<chars;ci=ci+1)begin
                bitmap=reference_glyph(text >> ((chars-1-ci)*8));
                for(gy=0;gy<7;gy=gy+1)for(gx=0;gx<8;gx=gx+1)begin
                    lit=0;if(gx<5)lit=bitmap[(6-gy)*5+4-gx];
                    for(sy=0;sy<scale;sy=sy+1)for(sx=0;sx<scale;sx=sx+1)
                        expect_pixel(px+(ci*8+gx)*scale+sx,py+gy*scale+sy,lit?foreground:background);
                end
            end
        end
    endtask
    task expect_zh;
        input integer px,py,width;
        input [287:0] label;
        input [23:0] foreground,background;
        integer gx,gy;
        reg [23:0] underlay;
        begin
            // Covers row 7->8, both halves, all 16 rows, padding and full clipping rectangle.
            for(gy=0;gy<16;gy=gy+1)for(gx=0;gx<width;gx=gx+1)begin
                underlay=background;
                if(background==BG && px+gx>=31 && px+gx<=544 && py+gy>=143 && py+gy<=280)
                    underlay=reference_scope(px+gx,py+gy,wave_previous,wave_current,scope_gain,wave_valid);
                expect_pixel(px+gx,py+gy,reference_lit(label,gx,gy)?foreground:underlay);
            end
        end
    endtask
    task expect_digits;
        input integer px,py,chars,value;
        input [23:0] foreground;
        reg [287:0] label;
        begin
            label=reference_number(ZH_BLANK,0,chars,value);
            expect_zh(px,py,chars*8,label,foreground,BG);
        end
    endtask
    task expect_wait;
        integer gx,gy;
        reg [23:0] expected;
        begin
            for(gy=0;gy<16;gy=gy+1)for(gx=0;gx<80;gx=gx+1)begin
                expected=reference_scope(256+gx,204+gy,0,0,0,0);
                if(reference_lit(ZH_WAIT,gx,gy))expected=AMBER;
                expect_pixel(256+gx,204+gy,expected);
            end
        end
    endtask
    task expect_wave;
        input integer previous,current,gain;
        integer p,px,py;
        begin
            wave_previous=previous;wave_current=current;scope_gain=gain;wave_valid=1;
            for(p=0;p<6;p=p+1)begin
                case(p)0:px=32;1:px=33;2:px=34;3:px=35;4:px=542;5:px=543;endcase
                for(py=144;py<=279;py=py+1)
                    expect_pixel(px,py,reference_scope(px,py,previous,current,gain,1));
            end
        end
    endtask

    integer i,state,px,py,col,row,address,output_file,scene;
    integer cyan_pixels=0,green_pixels=0,amber_pixels=0,alert_pixels=0,text_pixels=0,panel_pixels=0;
    reg [2047:0] output_path;
    reg [255:0] expected_text;
    reg [287:0] label;
    function signed [15:0] simulated_sample;
        input integer index;
        real mixed;
        begin
            mixed=10000.0*$sin(6.283185307179586*400.0*index*4.0/93750.0)+
                  5000.0*$sin(6.283185307179586*497.0*index*4.0/93750.0);
            simulated_sample=$rtoi(mixed);
        end
    endfunction
    initial begin
        reset_renderer;defaults;test_active=1;test_sweep=1;test_requested=16;voices=18;
        keys=12'hfff;guide_active=1;cue_mask=1;next_mask=2;wrong_mask=12'hffe;
        test_index=17;peak_percent=37;level_dbfs=-12;
        expect_zh(32,16,256,ZH_TEST_TITLE,CYAN,BG);
        expect_zh(368,16,256,ZH_TEST_SUBTITLE,AMBER,BG);
        expect_zh(320,88,256,ZH_CLOCK,TEXT,BG);
        expect_zh(32,88,256,ZH_FREQ_CONFIG,MUTED,BG);
        expect_zh(32,448,256,ZH_FREQ_CONFIG,MUTED,BG);
        expect_zh(320,448,256,ZH_FFT,AMBER,BG);
        expect_zh(32,64,208,reference_number(ZH_RMS_NEG,5,3,12),TEXT,BG);
        expect_zh(256,64,176,reference_number(ZH_PEAK,5,3,37),TEXT,BG);
        expect_zh(448,64,184,ZH_FIXED_VOLUME,TEXT,BG);
        // Independent row/column regression, including old erroneous x=272 origin.
        // Complete rectangles include the leading left half at x=256 and right half x=264.
        for(i=0;i<=32;i=i+1)begin
            test_requested=i;voices=32-i;
            expect_zh(32,40,208,reference_number(ZH_REQUESTED,5,2,i),TEXT,BG);
            expect_zh(256,40,176,reference_number(ZH_ACTIVE,5,2,32-i),GREEN,BG);
        end
        for(py=40;py<80;py=py+1)begin
            for(px=240;px<256;px=px+1)expect_pixel(px,py,BG);
            for(px=432;px<448;px=px+1)expect_pixel(px,py,BG);
            for(px=632;px<640;px=px+1)expect_pixel(px,py,BG);
        end
        for(i=0;i<32;i=i+1)begin
            col=i%8;row=i/8;test_index=i;
            $sformat(expected_text,"%02d",i);
            expect_text(36+64*col,299+32*row,1,expected_text,2,TEXT,PANEL);
            $sformat(expected_text,"%04dHZ",400+97*i);
            expect_text(36+64*col,312+32*row,1,expected_text,6,MUTED,PANEL);
            expect_zh(32,112,176,reference_number(ZH_INDEX,5,2,i),CYAN,BG);
            $sformat(expected_text,"%04d",400+97*i);
            expect_zh(224,112,208,reference_ascii(ZH_SET,5,expected_text,4),MUTED,BG);
            // Only bit i changes. Check every G/A glyph, detecting cross-cell aliases.
            for(state=0;state<4;state=state+1)begin
                test_gate=state[0]?(32'd1<<i):0;test_busy=state[1]?(32'd1<<i):0;
                for(address=0;address<32;address=address+1)begin
                    expect_text(60+64*(address%8),299+32*(address/8),1,"G",1,
                                (state[0] && address==i)?AMBER:MUTED,PANEL);
                    expect_text(76+64*(address%8),299+32*(address/8),1,"A",1,
                                (state[1] && address==i)?GREEN:MUTED,PANEL);
                end
            end
            expect_pixel(32+64*col,310+32*row,CYAN);expect_pixel(91+64*col,310+32*row,CYAN);
            expect_pixel(92+64*col,310+32*row,BG);expect_pixel(36+64*col,323+32*row,CYAN);
            expect_pixel(36+64*col,324+32*row,BG);
            test_sweep=0;expect_pixel(32+64*col,310+32*row,BORDER);test_sweep=1;
        end
        // Index 7/8,15/16,23/24,31 and y327/328,359/360,391/392,423/424.
        test_sweep=0;test_gate=0;test_busy=0;
        for(row=0;row<4;row=row+1)begin
            for(col=0;col<8;col=col+1)begin
                expect_pixel(36+col*64,327+row*32,BG);
                if(row<3)expect_pixel(36+col*64,328+row*32,BORDER);
                else expect_pixel(36+col*64,424,BG);
            end
        end
        expect_zh(448,40,184,ZH_FIXED,MUTED,BG);
        test_sweep=1;expect_zh(448,40,184,ZH_SWEEP,CYAN,BG);
        test_overrun=0;flags=0;expect_zh(448,112,184,ZH_SCHED_OK,GREEN,BG);
        expect_zh(552,160,80,ZH_ERROR,MUTED,BG);
        test_overrun=1;expect_zh(448,112,184,ZH_SCHED_BAD,ALERT,BG);
        expect_zh(552,144,80,ZH_SCHED,ALERT,BG);expect_zh(552,160,80,ZH_ERROR,ALERT,BG);
        test_overrun=0;flags=8'h80;expect_zh(552,160,80,ZH_ERROR,ALERT,BG);
        expect_zh(552,176,80,reference_flag_label(0),ALERT,BG);
        flags=8'h08;expect_zh(552,160,80,ZH_ERROR,ALERT,BG);
        expect_zh(552,192,80,reference_flag_label(4),ALERT,BG);
        level_dbfs=-128;expect_zh(32,64,208,reference_number(ZH_RMS_NEG,5,3,128),TEXT,BG);
        level_dbfs=127;expect_zh(32,64,208,reference_number(ZH_RMS_POS,5,3,127),TEXT,BG);
        peak_percent=255;expect_zh(256,64,176,reference_number(ZH_PEAK,5,3,255),TEXT,BG);
        expect_wave(-16384,16384,0);expect_wave(-32768,32767,15);
        wave_valid=0;expect_wait;de=0;expect_pixel(36,310,0);de=1;
        expect_pixel(640,310,0);expect_pixel(32,480,0);
        scene=5;if($value$plusargs("SCENE=%d",scene))begin end
        defaults;test_active=1;test_requested=16;voices=18;
        test_busy=32'h0003ffff;test_gate=32'h0000ffff;test_sweep=1;test_index=17;
        level_dbfs=-12;peak_percent=46;wave_valid=1;scope_gain=1;
        case(scene)
            1:begin test_requested=1;voices=2;test_busy=32'hc0000000;test_gate=32'h80000000;test_index=31;end
            2:begin test_requested=0;voices=0;test_busy=0;test_gate=0;test_sweep=0;end
            3:begin test_requested=32;voices=32;test_busy=32'hffffffff;test_gate=32'hffffffff;
                    test_overrun=1;flags=8'h88;end
            4:begin wave_valid=0;end
            5:begin test_requested=32;voices=32;test_busy=32'hffffffff;test_gate=32'hffffffff;
                    test_sweep=0;test_index=0;level_dbfs=-29;peak_percent=28;flags=0;end
        endcase
        output_path="hdmi_test_preview.ppm";if($value$plusargs("PPM=%s",output_path))begin end
        output_file=$fopen(output_path,"w");if(output_file==0)$fatal(1,"Cannot open HDL PPM");
        $fwrite(output_file,"P3\n# Chinese test UI, renderer RTL, synthetic PCM\n640 480\n255\n");
        for(py=0;py<480;py=py+1)for(px=0;px<640;px=px+1)begin
            address=0;if(px>=32 && px<=543)address=(px-32)>>1;
            wave_current=simulated_sample(address);wave_previous=simulated_sample(address==0?0:address-1);
            if(scene==2)begin wave_current=0;wave_previous=0;end
            sample_pixel(px,py);
            case({red,green,blue})
                CYAN:cyan_pixels=cyan_pixels+1;GREEN:green_pixels=green_pixels+1;
                AMBER:amber_pixels=amber_pixels+1;ALERT:alert_pixels=alert_pixels+1;
                TEXT:text_pixels=text_pixels+1;PANEL:panel_pixels=panel_pixels+1;
                BG,BORDER,GRID,MUTED:begin end
                default:$fatal(1,"Unexpected test palette %06h",{red,green,blue});
            endcase
            $fwrite(output_file,"%0d %0d %0d\n",red,green,blue);
        end
        $fclose(output_file);
        if(cyan_pixels<100 || green_pixels<100 || amber_pixels<100 || text_pixels<1000 || panel_pixels<50000)
            $fatal(1,"Implausible test frame occupancy");
        if(scene==3 && alert_pixels<100)$fatal(1,"Overrun scene lacks alerts");
        $display("HDMI_TEST_PREVIEW_TEST_PASS scene=%0d checks=%0d",scene,checks);$finish;
    end
    initial begin #50000000;$fatal(1,"Test preview timeout");end
endmodule

// Original complete test CDC top retained byte-for-byte.
module tb_hdmi_test_cdc;
    reg clk=0,rst_n=0;always #18.518519 clk=~clk;
    reg test_active=0,test_sweep=0,test_overrun=0;
    reg [5:0] test_requested=0,voices=0;
    reg [31:0] test_busy=0,test_gate=0;
    reg [4:0] test_index=0;
    wire locked,fs,cp,cn;wire [2:0] dp,dn;
    hdmi_live_display dut(
        .clk27(clk),.rst_n(rst_n),.sample_tick(1'b0),.pcm(16'd0),.peak(16'd0),
        .keys(12'h123),.timbre(4'd7),.note(7'd69),.note_valid(1'b1),
        .frequency_bcd(16'h0440),.volume_percent(8'd73),.level_dbfs(-8'sd12),
        .peak_percent(8'd37),.pitch(-9'sd10),.voices(voices),
        .pressure0(8'd88),.pressure1(8'd128),.flags(8'h20),
        .guide_active(1'b1),.guide_done(1'b0),.cue_mask(12'd1),.next_mask(12'd2),
        .wrong_mask(12'd4),.guide_step(6'd12),.guide_total(6'd42),
        .beat_progress(8'd180),.target_beats(2'd1),.clip(1'b0),
        .tmds_clk_p(cp),.tmds_clk_n(cn),.tmds_data_p(dp),.tmds_data_n(dn),
        .pll_locked(locked),.frame_tick(fs),
        .test_active(test_active),.test_requested(test_requested),
        .test_busy(test_busy),.test_gate(test_gate),.test_sweep(test_sweep),
        .test_index(test_index),.test_overrun(test_overrun));
    GSR GSR(.GSRI(1'b1));
    reg [241:0] expected,previous;
    integer i;
    task snapshot;
        begin
            expected={12'h123,4'd7,7'd69,1'b1,16'h0440,8'd73,-8'sd12,8'd37,
                      -9'sd10,voices,8'd88,8'd128,8'h20,1'b1,1'b0,
                      12'd1,12'd2,12'd4,6'd12,6'd42,8'd180,2'd1,1'b0,
                      test_active,test_requested,test_busy,test_gate,
                      test_sweep,test_index,test_overrun};
        end
    endtask
    task commit;
        begin
            @(negedge dut.pixel_clk);force dut.frame_tick=1'b1;
            @(posedge dut.pixel_clk);#1;force dut.frame_tick=1'b0;
            repeat(16)@(posedge dut.pixel_clk);#1;
        end
    endtask
    task verify;
        begin
            snapshot;commit;commit;
            if(dut.source_status!==expected || dut.display_status!==expected)
                $fatal(1,"242-bit coherent test snapshot packing failed");
            if({dut.u_dashboard.test_active,dut.u_dashboard.test_requested,
                dut.u_dashboard.test_busy,dut.u_dashboard.test_gate,
                dut.u_dashboard.test_sweep,dut.u_dashboard.test_index,
                dut.u_dashboard.test_overrun}!==expected[77:0])
                $fatal(1,"Renderer test-port unpack mismatch");
            if(dut.u_dashboard.voices!==voices)$fatal(1,"Actual busy count wiring failed");
            previous=dut.display_status;
        end
    endtask
    initial begin
        force dut.frame_tick=1'b0;
        #200;rst_n=1;wait(locked);wait(dut.video_rst_n);verify;
        for(i=0;i<32;i=i+1)begin
            @(negedge clk);
            test_active=1;test_requested=32;voices=1;test_busy=32'd1<<i;
            test_gate=~(32'd1<<i);test_sweep=1;test_index=i;test_overrun=i[0];
            repeat(20)begin
                @(posedge dut.pixel_clk);#1;
                if(dut.display_status!==previous)$fatal(1,"Test fields tear between frame commits");
            end
            verify;
        end
        // 页面退出先清门控，busy 的尾音仍活动，active 在交接完毕前保持 1。
        test_gate=0;test_requested=0;test_overrun=0;verify;
        if(dut.d_test_active!==1 || dut.d_test_busy!==32'h80000000)
            $fatal(1,"Transition lost test ownership/release busy");
        voices=0;test_busy=0;verify;
        test_active=0;test_sweep=0;test_index=0;verify;
        // reset/relock 丢弃在途请求；242 位端口恢复后重新相干提交。
        rst_n=0;#100;rst_n=1;wait(locked);wait(dut.video_rst_n);verify;
        release dut.frame_tick;
        $display("HDMI_TEST_CDC_TEST_PASS width=242 walking_bits=32 entry_exit_reset");
        $finish;
    end
    initial begin #1000000;$fatal(1,"OSC CDC timeout");end
endmodule
